# full-tests — what the worker does

Dispatches `.github/workflows/tests-full.yml` on the default branch, finds the run it started,
waits for it, and parks the item at a failure with the run's link when the tests are red. The
workflow also runs on every push to main; this task is the nightly run, since the scheduler is the
repo's only cron.
// full-tests — run the Full tests workflow on the default branch and wait for its verdict.
//
// The tests need setup-python, setup-node and Playwright's browser, which are `uses:` steps only a
// workflow job can run, so the workflow carries the steps and this task owns when they run.

import { fail, github } from '@claudinite/sdk';
import { makeGh } from '../github-api.mjs';

export const WORKFLOW_FILE = 'tests-full.yml';
export const RUN_APPEARS_WITHIN_MS = 3 * 60 * 1000;
export const RUN_FINISHES_WITHIN_MS = 25 * 60 * 1000;

export async function worker({ log, repo, defaultBranch, gh = makeGh(), dispatch = github.dispatchWorkflow, now = () => Date.now(), sleep = (ms) => new Promise((r) => { setTimeout(r, ms); }) }) {
  const since = new Date(now() - 60 * 1000).toISOString();
  try {
    await dispatch({ workflow: WORKFLOW_FILE, ref: defaultBranch });
  } catch (e) {
    fail('failure', `dispatching ${WORKFLOW_FILE} on ${defaultBranch} failed: ${e?.message ?? e}`);
  }

  const started = now();
  let run = null;
  while (!run && now() - started < RUN_APPEARS_WITHIN_MS) {
    await sleep(10 * 1000);
    const { status: listStatus, json } = await gh(`/repos/${repo}/actions/workflows/${WORKFLOW_FILE}/runs?event=workflow_dispatch&per_page=20`);
    if (listStatus !== 200) continue;
    run = (json?.workflow_runs ?? []).find((r) => r.created_at >= since) ?? null;
  }
  if (!run) fail('failure', `${WORKFLOW_FILE} was dispatched but no run appeared within three minutes`);
  log(`full tests started: ${run.html_url}`);

  while (run.status !== 'completed') {
    if (now() - started > RUN_FINISHES_WITHIN_MS) fail('failure', `the full tests did not finish in time: ${run.html_url}`);
    await sleep(20 * 1000);
    const { status: readStatus, json } = await gh(`/repos/${repo}/actions/runs/${run.id}`);
    if (readStatus === 200 && json) run = json;
  }
  if (run.conclusion !== 'success') fail('failure', `the full tests ended ${run.conclusion} on ${defaultBranch}: ${run.html_url}`);
  log(`full tests passed: ${run.html_url}`);
}
# Improve the finders on the ground truth just added

The ground truth people submitted from the NoR Finder page was added to `studies/nor/detection/lab/ground_truth/`
on the pull request named under "Delivered by code-work", with the quality baseline re-recorded
against it. Work on that pull request's branch and push onto it; never open another, never merge.

Follow the [improve-on-ground-truth](../../skills/improve-on-ground-truth/SKILL.md) skill: re-score
every finder on every ground-truth image and report how each changed from the base branch, then
make the finders propose candidates at the newly marked missing NoRs, then improve overall quality.

- A change that loses a real NoR, passes a new not-NoR or stops proposing a candidate at a missing
  mark is not yours to accept: leave it out, or describe it in the pull request for the owner.
- When nothing you tried kept its gains, say so in the pull request with what you tried; the ground
  truth it adds stands on its own.
- Add your report to the pull request's body below what is already there, and log every attempt in
  `studies/nor/detection/lab/ledger.md`.
// The intake, by code: every open issue labelled new-ground-truth has its attached file added to the
// ground-truth data set (studies/nor/detection/ground_truth.py ingest), the quality baseline is re-recorded against the
// new reference, and the result is opened as this run's pull request, which closes the issues it took
// when merged. The task's automerge policy is nothing, so the pull request stays open: the agent works on
// it next, and only a person merges it. A submission that cannot be used gets a comment saying why and loses the label, so it waits
// for its author instead of being retried every day. The agent is asked for only when something was added.
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { commitMessage, git as engineGit, github } from '@claudinite/sdk';
import { makeGh } from '../github-api.mjs';
import { LABEL } from './label.mjs';

const MARK = '<!-- ground-truth-intake -->';

async function paged(gh, path) {
  const out = [];
  for (let page = 1; ; page += 1) {
    const { status, json } = await gh(`${path}${path.includes('?') ? '&' : '?'}per_page=100&page=${page}`);
    if (status !== 200) throw new Error(`GitHub answered ${status} for ${path}`);
    out.push(...json);
    if (json.length < 100) return out;
  }
}

// The intake's commit, on the scratch tree, pushed as the run's branch: the push goes through the
// engine, which holds the token and refuses anything touching the default branch.
async function pushBranch(wt, branch, message) {
  const local = (...args) => execFileSync('git', ['-C', wt, ...args], { encoding: 'utf8' }).trim();
  local('add', '--', 'studies/nor/detection/lab');
  local('-c', 'user.name=claudinite', '-c', 'user.email=claudinite@users.noreply.github.com', '-c', 'commit.gpgsign=false',
    'commit', '--quiet', '-m', commitMessage(message));
  const sha = local('rev-parse', 'HEAD');
  const pushed = await engineGit('push', '--force', 'origin', `${sha}:refs/heads/${branch}`);
  if (pushed.code !== 0) throw new Error(`pushing ${branch}: ${pushed.stderr.trim()}`);
  return sha;
}

export async function worker({ log, root, repo, defaultBranch, target, gh = makeGh(), token = process.env.GITHUB_TOKEN }) {
  const open = (await paged(gh, `/repos/${repo}/issues?state=open&labels=${LABEL}`)).filter((i) => !i.pull_request);
  const issues = [];
  for (const i of open) {
    const comments = await paged(gh, `/repos/${repo}/issues/${i.number}/comments`);
    issues.push({ number: i.number, title: i.title, body: i.body ?? '', comments: comments.map((c) => c.body ?? '') });
  }
  log(`${issues.length} open issue(s) labelled ${LABEL}: ${issues.map((i) => `#${i.number}`).join(' ')}`);

  // a scratch checkout of the base, so nothing here touches the executor's own
  const tmp = mkdtempSync(join(tmpdir(), 'gt-intake-'));
  const wt = join(tmp, 'repo');
  const git = (...args) => execFileSync('git', ['-C', root, ...args], { encoding: 'utf8' });
  const fetched = await engineGit('fetch', '--quiet', 'origin', defaultBranch ?? 'main');
  if (fetched.code !== 0) throw new Error(`fetching ${defaultBranch ?? 'main'}: ${fetched.stderr.trim()}`);
  git('worktree', 'add', '--quiet', '--detach', wt, 'FETCH_HEAD');
  try {
    const py = join(tmp, 'venv', 'bin', 'python');
    const run = (cmd, args, env = {}) => execFileSync(cmd, args, { cwd: wt, encoding: 'utf8', env: { ...process.env, ...env }, stdio: ['ignore', 'pipe', 'inherit'] });
    run('python3', ['-m', 'venv', join(tmp, 'venv')]);
    run(py, ['-m', 'pip', 'install', '--quiet', '-r', 'requirements.txt']);
    writeFileSync(join(tmp, 'issues.json'), JSON.stringify(issues));
    run(py, ['studies/nor/detection/ground_truth.py', 'ingest', join(tmp, 'issues.json'), '--out', join(tmp, 'result.json')], { GITHUB_TOKEN: token });
    const { added, refused } = JSON.parse(readFileSync(join(tmp, 'result.json'), 'utf8'));
    log(`added ${added.length ? added.map((n) => `#${n}`).join(' ') : 'nothing'}; refused ${Object.keys(refused).length}`);

    for (const [n, why] of Object.entries(refused)) {
      await github.createComment({ issue: Number(n), body:
        `${MARK}\nThis ground truth could not be added: ${why}.\n\n`
        + `Export it again from the NoR Finder page with the image opened from Google Drive, attach the new file here, `
        + `and put the \`${LABEL}\` label back; the next daily intake will take it.` });
      await gh(`/repos/${repo}/issues/${n}/labels/${LABEL}`, { method: 'DELETE' });
    }
    if (!added.length) return undefined;

    run(py, ['studies/nor/detection/ground_truth.py', 'fetch']);
    const scores = run(py, ['studies/nor/tests/test_quality.py', '--accept']).split('\n').filter((l) => / real found, /.test(l)).join('\n');
    const body = [
      `Adds ${added.length} ground-truth submission(s) from the NoR Finder page to \`studies/nor/detection/lab/ground_truth/\` and re-records the quality baseline against the new reference (submitted labels outrank older ones: studies/nor/docs/requirements.md R10).`,
      '',
      ...added.map((n) => `Closes #${n}`),
      '',
      'Every finder on every ground-truth image, as now recorded:',
      '```',
      scores.trim(),
      '```',
    ].join('\n');
    const branch = target.branch;
    if (!branch) throw new Error('the run was handed no target branch to open its pull request from');
    await pushBranch(wt, branch, `Add ground truth from ${added.map((n) => `#${n}`).join(', ')}`);
    const pr = await github.openPr({ title: `Ground truth: add ${added.map((n) => `#${n}`).join(', ')}`, body, head: branch, base: defaultBranch ?? 'main' });
    const d = { number: pr.number, branch };
    log(`opened #${d.number} on ${d.branch}, left open for the agent`);
    return { requestAgent: { delivered: { pr: d.number, branch: d.branch }, reason: { code: 'ground-truth-added', detail: `${added.length} submission(s) added` } } };
  } finally {
    try { git('worktree', 'remove', '--force', wt); } catch { /* the scratch tree goes with tmp */ }
    rmSync(tmp, { recursive: true, force: true });
  }
}
// The REST calls this pack's workers make that @claudinite/sdk names no action for, under the job's
// own token, which the executor leaves in every work step's environment. Each one moves to its SDK
// action once the engine offers it.
//
// `gh(path)` reads and `gh(path, { method, body })` writes, answering `{ status, json }`: a non-2xx is
// an answer rather than a throw, so a caller judges the status before trusting the body.

const API = process.env.GITHUB_API_URL || 'https://api.github.com';

export function makeGh({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
  return async function gh(path, { method = 'GET', body } = {}) {
    const res = await fetchImpl(`${api}${path}`, {
      method,
      headers: {
        accept: 'application/vnd.github+json',
        'x-github-api-version': '2022-11-28',
        ...(token ? { authorization: `Bearer ${token}` } : {}),
        'user-agent': 'claudinite-task',
        ...(body ? { 'content-type': 'application/json' } : {}),
      },
      ...(body ? { body: JSON.stringify(body) } : {}),
    });
    let json = null;
    try { json = await res.json(); } catch { json = null; }
    return { status: res.status, json };
  };
}
package checks

import (
	"fmt"
	"regexp"
	"slices"

	"claudinite.com/checksdk"
)

// A still-open PR let a pack element's provenance file grow a `born` entry, a
// `trigger-changed` entry and four further unentried edits before the owner had
// the session wipe it and write one entry covering the whole PR (nor-finder
// provenance/provenance-once-per-pr.md). The append-only growth rule
// (changing-pack-elements) reads naturally as "every landing change gets its
// own entry": right once a PR has merged, wrong while it is still iterating,
// since an in-flight PR's own pushes are amendments to one not-yet-landed
// decision, not a sequence of landed ones.
//
// `_declined.md` is exempt: a growth run legitimately appends several distinct
// candidates' `declined` entries there in one pass. A backfilling-provenance
// run, whose PR title is `Provenance: backfill <pack>`, writes a new file's
// whole history in one pass on purpose, so its branch is exempt too.
var (
	provenanceFile = regexp.MustCompile(`(^|/)provenance/[^/]+\.md$`)
	declinedFile   = regexp.MustCompile(`(^|/)provenance/_declined\.md$`)
	entryHeader    = regexp.MustCompile(`^## \d{4}-\d{2}-\d{2} · `)
	backfillRun    = regexp.MustCompile(`^Provenance: backfill\b`)
)

func init() {
	checksdk.Register(checksdk.Check{
		ID:     "provenance-once-per-pr",
		Tags:   []string{"work"},
		OnFail: "advise",
		Since:  "2026-09-28",
		Doc:    ".claudinite/local/packs/nor-finder/provenance/provenance-once-per-pr.md",
		Why:    "the append-only growth rule is for landed history; squashing a PR's own mid-flight entries into one before merge is what the owner asked for after one local-pack element accumulated two",
		Run:    provenanceOncePerPR,
	})
}

func provenanceOncePerPR(repo checksdk.Repo) []checksdk.Finding {
	if repo.OnDefaultBranch() || slices.ContainsFunc(repo.CommitMessages(), backfillRun.MatchString) {
		return nil
	}
	var out []checksdk.Finding
	for _, f := range repo.ChangedFiles() {
		if !provenanceFile.MatchString(f) || declinedFile.MatchString(f) {
			continue
		}
		var added []checksdk.Line
		for _, l := range repo.AddedLines([]string{f}) {
			if entryHeader.MatchString(l.Text) {
				added = append(added, l)
			}
		}
		if len(added) < 2 {
			continue
		}
		out = append(out, checksdk.Finding{
			Path:     f,
			Line:     added[len(added)-1].Line,
			Sentence: fmt.Sprintf("this still-open PR adds %d provenance entries to %s", len(added), f),
			Fix:      "squash this PR's own entries into one before merging: a still-open PR's provenance is one decision in progress, not a landed history yet",
		})
	}
	return out
}
